package ru.neverland.townypopulation.model;

import java.math.*;
import java.util.*;

/** Derived virtual resident groups. Nothing here creates residents, jobs, items, currency or a second food debit. */
public final class DistrictCohorts {
    private DistrictCohorts(){}
    public static final String CITY="city";
    public record Service(String id,String title,int served,int plots,boolean known){public Service{if(id==null||!id.matches("[a-z0-9_]{1,32}")||title==null||title.isBlank()||title.length()>80||plots<1||served<0||served>plots)throw new IllegalArgumentException("Неверная потребность района");}}
    public record District(String id,String name,String type,int plots,int connected,boolean connectionKnown,List<Service> services){public District{services=List.copyOf(services);if(id==null||!id.matches("[a-z0-9_-]{1,32}")||name==null||name.isBlank()||name.length()>80||type==null||!type.matches("[A-Z_]{1,32}")||plots<1||connected<0||connected>plots||services.size()>8)throw new IllegalArgumentException("Неверный район населения");var ids=new HashSet<String>();for(var service:services)if(!ids.add(service.id())||service.plots()!=plots)throw new IllegalArgumentException("Не совпадает площадь потребности района");}}
    public record Source(String id,int housing,int jobs){public Source{if(id==null||!(id.equals("@base")||id.matches("[a-z0-9_]{1,64}"))||housing<0||housing>10_000_000||jobs<0||jobs>10_000_000)throw new IllegalArgumentException("Неверный источник возможностей города");}}
    public record Input(int population,int workforce,int employed,int housing,int jobs,BigDecimal foodSupply,BigDecimal waterSupply,BigDecimal foodPerResident,BigDecimal waterPerResident,Map<String,Source> sources,Map<String,District> districts,Map<String,String> assignments){
        public Input{sources=Map.copyOf(sources);districts=Map.copyOf(districts);assignments=Map.copyOf(assignments);if(population<0||population>1_000_000||workforce<0||workforce>population||employed<0||employed>workforce||housing<0||housing>10_000_000||jobs<0||jobs>10_000_000||employed>jobs||sources.size()>1024||districts.size()>128||assignments.size()>1024)throw new IllegalArgumentException("Неверные итоги населения города");amount(foodSupply,1_000_000_000);amount(waterSupply,1_000_000_000);amount(foodPerResident,1000);amount(waterPerResident,1000);for(var e:sources.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("Не совпадает источник населения");for(var e:districts.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("Не совпадает район населения");for(var e:assignments.entrySet())if(e.getKey().equals("@base")||!e.getKey().matches("[a-z0-9_]{1,64}")||!districts.containsKey(e.getValue()))throw new IllegalArgumentException("Площадка ссылается на неизвестный район");}
    }
    public record Group(String id,String name,District district,int population,int housing,int jobs,int workforce,int employed,int unemployed,int other,BigDecimal foodDemand,BigDecimal waterDemand,BigDecimal foodSupply,BigDecimal waterSupply){
        public Group{Objects.requireNonNull(id);Objects.requireNonNull(name);if(population<0||housing<0||jobs<0||workforce<0||workforce>population||employed<0||employed>workforce||unemployed!=workforce-employed||other!=population-workforce||district==null&&!id.equals(CITY)||district!=null&&!id.equals("district:"+district.id()))throw new IllegalArgumentException("Неверная группа населения");amount(foodDemand,1_000_000_000);amount(waterDemand,1_000_000_000);amount(foodSupply,1_000_000_000);amount(waterSupply,1_000_000_000);}
    }
    public record Result(List<Group> groups,int population,int housing,int jobs,int workforce,int employed,BigDecimal foodDemand,BigDecimal waterDemand,BigDecimal foodSupply,BigDecimal waterSupply){public Result{groups=List.copyOf(groups);if(groups.size()>129)throw new IllegalArgumentException("Слишком много групп населения");var ids=new HashSet<String>();for(var group:groups)if(!ids.add(group.id()))throw new IllegalArgumentException("Повтор группы населения");if(groups.stream().mapToLong(Group::population).sum()!=population||groups.stream().mapToLong(Group::housing).sum()!=housing||groups.stream().mapToLong(Group::jobs).sum()!=jobs||groups.stream().mapToLong(Group::workforce).sum()!=workforce||groups.stream().mapToLong(Group::employed).sum()!=employed||sum(groups,Group::foodDemand).compareTo(foodDemand)!=0||sum(groups,Group::waterDemand).compareTo(waterDemand)!=0||sum(groups,Group::foodSupply).compareTo(foodSupply)!=0||sum(groups,Group::waterSupply).compareTo(waterSupply)!=0)throw new IllegalArgumentException("Группы не сохраняют городские итоги");}}
    private static void amount(BigDecimal value,long maximum){if(value==null||value.signum()<0||value.compareTo(BigDecimal.valueOf(maximum))>0||value.precision()>40||Math.abs((long)value.scale())>30)throw new IllegalArgumentException("Неверные единицы снабжения");}
    private static BigDecimal sum(List<Group> groups,java.util.function.Function<Group,BigDecimal> field){var sum=BigDecimal.ZERO;for(var group:groups)sum=sum.add(field.apply(group));return sum;}
    private record Remainder(String id,BigInteger value){}
    /** Largest remainder with stable key ties; works even when amount*weight exceeds long. */
    private static Map<String,BigInteger> distribute(BigInteger amount,Map<String,BigInteger> weights){
        if(amount.signum()<0||!weights.containsKey(CITY))throw new IllegalArgumentException("Неверное распределение");var result=new TreeMap<String,BigInteger>();var total=BigInteger.ZERO;for(var e:weights.entrySet()){if(e.getValue().signum()<0)throw new IllegalArgumentException("Отрицательный вес");total=total.add(e.getValue());result.put(e.getKey(),BigInteger.ZERO);}if(total.signum()==0){result.put(CITY,amount);return Map.copyOf(result);}
        var remainders=new ArrayList<Remainder>();var used=BigInteger.ZERO;for(var e:weights.entrySet()){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Районный расчёт остановлен");var qr=amount.multiply(e.getValue()).divideAndRemainder(total);result.put(e.getKey(),qr[0]);used=used.add(qr[0]);remainders.add(new Remainder(e.getKey(),qr[1]));}int left=amount.subtract(used).intValueExact();remainders.sort(Comparator.comparing(Remainder::value).reversed().thenComparing(Remainder::id));for(int i=0;i<left;i++){String key=remainders.get(i).id();result.put(key,result.get(key).add(BigInteger.ONE));}return Map.copyOf(result);
    }
    private static Map<String,BigDecimal> supply(BigDecimal amount,Map<String,BigInteger> weights){int scale=Math.max(6,amount.scale());var units=distribute(amount.setScale(scale).unscaledValue(),weights);var result=new HashMap<String,BigDecimal>();units.forEach((id,value)->result.put(id,new BigDecimal(value,scale)));return Map.copyOf(result);}
    public static Result calculate(Input input){
        var housingWeights=new TreeMap<String,BigInteger>();var jobWeights=new TreeMap<String,BigInteger>();housingWeights.put(CITY,BigInteger.ZERO);jobWeights.put(CITY,BigInteger.ZERO);for(String id:input.districts().keySet()){housingWeights.put("district:"+id,BigInteger.ZERO);jobWeights.put("district:"+id,BigInteger.ZERO);}
        for(var source:input.sources().values()){String district=input.assignments().get(source.id());String group=district==null?CITY:"district:"+district;housingWeights.merge(group,BigInteger.valueOf(source.housing()),BigInteger::add);jobWeights.merge(group,BigInteger.valueOf(source.jobs()),BigInteger::add);}
        var rawHousing=housingWeights.values().stream().reduce(BigInteger.ZERO,BigInteger::add);if(rawHousing.compareTo(BigInteger.valueOf(input.housing()))<0)housingWeights.merge(CITY,BigInteger.valueOf(input.housing()).subtract(rawHousing),BigInteger::add);
        var rawJobs=jobWeights.values().stream().reduce(BigInteger.ZERO,BigInteger::add);if(rawJobs.compareTo(BigInteger.valueOf(input.jobs()))<0)jobWeights.merge(CITY,BigInteger.valueOf(input.jobs()).subtract(rawJobs),BigInteger::add);
        var housing=distribute(BigInteger.valueOf(input.housing()),housingWeights);var jobs=distribute(BigInteger.valueOf(input.jobs()),jobWeights);var residents=distribute(BigInteger.valueOf(input.population()),housing);var workers=distribute(BigInteger.valueOf(input.workforce()),residents);var employed=distribute(BigInteger.valueOf(input.employed()),workers);var food=supply(input.foodSupply(),residents);var water=supply(input.waterSupply(),residents);
        var groups=new ArrayList<Group>();for(String id:housingWeights.keySet()){var district=id.equals(CITY)?null:input.districts().get(id.substring("district:".length()));int people=residents.get(id).intValueExact(),working=workers.get(id).intValueExact(),hired=employed.get(id).intValueExact();groups.add(new Group(id,district==null?"Не распределено по районам":district.name(),district,people,housing.get(id).intValueExact(),jobs.get(id).intValueExact(),working,hired,working-hired,people-working,input.foodPerResident().multiply(BigDecimal.valueOf(people)),input.waterPerResident().multiply(BigDecimal.valueOf(people)),food.get(id),water.get(id)));}
        return new Result(groups,input.population(),input.housing(),input.jobs(),input.workforce(),input.employed(),input.foodPerResident().multiply(BigDecimal.valueOf(input.population())),input.waterPerResident().multiply(BigDecimal.valueOf(input.population())),input.foodSupply(),input.waterSupply());
    }
}
